import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0012 — Certified bounded-error rewrites (eps machinery)","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/plans/0012-bounded-error-rewrites.md","filePath":"vendored/graphopt/project/plans/0012-bounded-error-rewrites.md"}`),a={name:`graphopt/project/plans/0012-bounded-error-rewrites.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0012-—-certified-bounded-error-rewrites-eps-machinery" tabindex="-1">Plan 0012 — Certified bounded-error rewrites (eps machinery) <a class="header-anchor" href="#plan-0012-—-certified-bounded-error-rewrites-eps-machinery" aria-label="Permalink to “Plan 0012 — Certified bounded-error rewrites (eps machinery)”">​</a></h1><p>Status: draft — justified by literature (xKV, CommonKV, CLA, CHAI, ReLU-sparsity): real models carry structure <em>approximately</em> — exact-factor gates decline them, approximate literature compresses them without certificates. CatOpt&#39;s differentiator: rewrites that carry a proven error envelope.</p><h2 id="idea" tabindex="-1">Idea <a class="header-anchor" href="#idea" aria-label="Permalink to “Idea”">​</a></h2><p>Extend <code>Rewrite</code>/<code>_offer_witness</code> with <code>error_bound</code>: a rewrite may apply when lhs ≈ rhs within a <em>certified</em> bound propagated to the delivered module&#39;s verify report — not fp64-exact, but proven <code>max_rel ≤ bound</code> against the original on real inputs, recorded in <code>stats[&quot;error_bounds&quot;]</code> and in the exported manifest.</p><h2 id="targets-ranked-by-evidence" tabindex="-1">Targets (ranked by evidence) <a class="header-anchor" href="#targets-ranked-by-evidence" aria-label="Permalink to “Targets (ranked by evidence)”">​</a></h2><ol><li><strong>Approximate KV latent sharing</strong> — xKV: cross-layer KV singular vectors align (8x compression training-free). Our KVLatentShare fires only near-exactly today; bounded-error accepts the aligned but imperfect case with bound = reconstruction error + propagated attention-path sensitivity.</li><li><strong>Attention-score head sharing</strong> — CHAI/head-clustering: heads with correlated QK share compute. Exact case already covered by WeightTie; bounded case = near-shared weights.</li><li><strong>Low-rank weight folding</strong> — FFN low-rank (2.6x at 32% params): W ≈ A·B with bound = discarded singular mass.</li><li><strong>Dead-neuron elision</strong> — structurally-zero rows exact; nearly- dead rows bounded.</li></ol><h2 id="machinery-mostly-exists" tabindex="-1">Machinery (mostly exists) <a class="header-anchor" href="#machinery-mostly-exists" aria-label="Permalink to “Machinery (mostly exists)”">​</a></h2><ul><li><code>eps.py</code>/<code>ibp.py</code> — interval-bound propagation already in core.</li><li><code>verify</code> accepts rtol — a bounded rewrite verifies with its bound as tolerance AND records the bound (two-sided: measured max_rel + certified bound ≤ user budget).</li><li><code>error_budget=</code> kwarg on search/optimize: default None (exact only — behavior unchanged); opt-in float enables bounded rewrites.</li></ul><h2 id="honest-position" tabindex="-1">Honest position <a class="header-anchor" href="#honest-position" aria-label="Permalink to “Honest position”">​</a></h2><p>This is lossy-but-proven — different from compression papers (they give perplexity deltas, we give input-level error envelopes on the delivered function). Never silent: stats + manifest always report which bounded rewrites fired and their bounds.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};